SELECT ?s ?class ?tsid WHERE {
  ?s ref:hasLabel ?lbl .
  FILTER(?lbl="Perimeter_top_ZN_2")
  OPTIONAL{ ?s ref:hasTimeseriesId ?tsid }
}

SELECT ?p ?class WHERE {
  ?zone a brick:Zone ; brick:hasLabel ?lbl .
  FILTER(?lbl="Perimeter_top_ZN_2") .
  ?p brick:hasProperty ?zone .
}

SELECT ?point ?point_class ?point_label ?tsid WHERE {
  ?point brick:hasSubArea ?zone .
  ?point a ?point_class .
  OPTIONAL{ ?point rdfs:label ?point_label }
  OPTIONAL{ ?point ref:hasTimeseriesId ?tsid }
}

SELECT ?tsid ?ext WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z03.Occupancy_Sensor> ?p ?o .
  FILTER(?p = ref:hasTimeseriesId || ?p = ref:hasExternalReference)
  BIND(IF(?p=ref:hasTimeseriesId, ?o, "ext") AS ?tsid)
  BIND(IF(?p=ref:hasExternalReference, ?o, "ext") AS ?ext)
}

